import Product from './Product.js';
import images from '../assets';
export default function ProductsList() {
  const products = [
    { id: 1, name: 'Product 1', price: 100, description: 'This is product 1', img_src: '/assets/images/product1.png' },
    { id: 2, name: 'Product 2', price: 200, description: 'This is product 2', img_src: '/assets/images/product1.png' },
  ];
  return (
    <div>
      <h1>Products List</h1>
      <ul>
        {products.map(product => (
          <Product key={product.id} {...product} />
        ))}
      </ul>
    </div>
  );
}
